import java.util.Arrays;
import java.util.Comparator;

public final class BubbleSortTest {

    private BubbleSortTest() {
    }

    public static void main(String[] args) {
        testPrimitiveSort();
        testGenericSort();
        testCustomComparator();
        testNoOpCases();
        System.out.println("BubbleSort tests passed.");
    }

    private static void testPrimitiveSort() {
        int[] values = { 5, 1, 4, 2, 8 };

        BubbleSort.sort(values);

        assertArrayEquals(new int[] { 1, 2, 4, 5, 8 }, values, "primitive sort");
    }

    private static void testGenericSort() {
        Integer[] values = { 9, 3, 7, 1, 5 };

        BubbleSort.sort(values);

        assertArrayEquals(new Integer[] { 1, 3, 5, 7, 9 }, values, "generic sort");
    }

    private static void testCustomComparator() {
        String[] values = { "bbb", "a", "cc" };

        BubbleSort.sort(values, Comparator.comparingInt(String::length));

        assertArrayEquals(new String[] { "a", "cc", "bbb" }, values, "custom comparator");
    }

    private static void testNoOpCases() {
        int[] empty = {};
        BubbleSort.sort(empty);
        assertArrayEquals(new int[] {}, empty, "empty primitive array");

        String[] single = { "only" };
        BubbleSort.sort(single);
        assertArrayEquals(new String[] { "only" }, single, "single-element generic array");
    }

    private static void assertArrayEquals(int[] expected, int[] actual, String label) {
        if (!Arrays.equals(expected, actual)) {
            throw new AssertionError(label + " failed: expected " + Arrays.toString(expected)
                    + " but got " + Arrays.toString(actual));
        }
    }

    private static <T> void assertArrayEquals(T[] expected, T[] actual, String label) {
        if (!Arrays.equals(expected, actual)) {
            throw new AssertionError(label + " failed: expected " + Arrays.toString(expected)
                    + " but got " + Arrays.toString(actual));
        }
    }
}

import java.util.Comparator;
import java.util.Objects;

public final class BubbleSort {

    @FunctionalInterface
    private interface IndexComparator {
        boolean isOutOfOrder(int leftIndex, int rightIndex);
    }

    @FunctionalInterface
    private interface IndexSwapper {
        void swap(int leftIndex, int rightIndex);
    }

    private BubbleSort() {
    }

    public static void sort(int[] values) {
        Objects.requireNonNull(values, "values");

        if (values.length < 2) {
            return;
        }

        bubbleSort(values.length,
                (leftIndex, rightIndex) -> values[leftIndex] > values[rightIndex],
                (leftIndex, rightIndex) -> swap(values, leftIndex, rightIndex));
    }

    public static <T extends Comparable<? super T>> void sort(T[] values) {
        sort(values, Comparator.naturalOrder());
    }

    public static <T> void sort(T[] values, Comparator<? super T> comparator) {
        Objects.requireNonNull(values, "values");
        Objects.requireNonNull(comparator, "comparator");

        if (values.length < 2) {
            return;
        }

        bubbleSort(values.length,
                (leftIndex, rightIndex) -> comparator.compare(values[leftIndex], values[rightIndex]) > 0,
                (leftIndex, rightIndex) -> swap(values, leftIndex, rightIndex));
    }

    private static void bubbleSort(int length, IndexComparator comparator, IndexSwapper swapper) {
        for (int end = length - 1; end > 0; end--) {
            boolean swapped = false;

            for (int index = 0; index < end; index++) {
                if (comparator.isOutOfOrder(index, index + 1)) {
                    swapper.swap(index, index + 1);
                    swapped = true;
                }
            }

            if (!swapped) {
                break;
            }
        }
    }

    private static void swap(int[] values, int leftIndex, int rightIndex) {
        int temp = values[leftIndex];
        values[leftIndex] = values[rightIndex];
        values[rightIndex] = temp;
    }

    private static <T> void swap(T[] values, int leftIndex, int rightIndex) {
        T temp = values[leftIndex];
        values[leftIndex] = values[rightIndex];
        values[rightIndex] = temp;
    }
}

